// Package cron writes the scheduled jobs of an account.
//
// An account's jobs are one file in /etc/cron.d (lpanel-<user>), written whole
// each time, and run by the system's cron as that account (the user field of
// the line), never as root. Everything in the file is made by the agent from
// parts it has checked: the schedule is five fields of numbers, ranges, steps
// and lists (or one of a few @ words), the command is one line of printable
// text with no byte cron treats specially (a % is written \%), and the
// environment lines are the agent's own (the account's home and its private
// temporary folder, no mail).
//
// A job may not run more often than every five minutes, so one account cannot
// make cron a way to keep the server busy; and an account has at most 20 jobs.
package cron

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"

	"lpa/internal/fsutil"
	"lpa/internal/protocol"
)

// Limits.
const (
	MaxJobs       = 20
	MaxCommand    = 1000
	MinuteMinimum = 5 // a job runs at most once in this many minutes
)

// Job is one scheduled command.
type Job struct {
	// Schedule is five fields (minute hour day-of-month month day-of-week) or
	// @hourly, @daily, @weekly, @monthly, @yearly.
	Schedule string `json:"schedule"`
	Command  string `json:"command"`
}

// Args are cron.apply's arguments: an account's whole list of jobs.
type Args struct {
	Username string `json:"username"`
	// Suspended accounts run nothing: their file is removed (the panel keeps the jobs).
	Suspended bool  `json:"suspended"`
	Jobs      []Job `json:"jobs"`
}

// Result is what cron.apply answers.
type Result struct {
	Username string `json:"username"`
	Jobs     int    `json:"jobs"`
	Changed  bool   `json:"changed"`
}

// Manager writes the files. Paths and lookups are fields so tests can use a folder.
type Manager struct {
	Dir string // /etc/cron.d
	// Owner finds an account's user id, group id and home (an error when LPanel did not make it).
	Owner func(name string) (uid, gid int, home string, err error)
	// Chown gives a file to a user (tests change it).
	Chown func(path string, uid, gid int) error
}

// Defaults fills in what a server has.
func (m *Manager) Defaults() {
	if m.Dir == "" {
		m.Dir = "/etc/cron.d"
	}
	if m.Chown == nil {
		m.Chown = os.Chown
	}
}

var (
	userRule  = regexp.MustCompile(`^[a-z][a-z0-9]{1,15}$`)
	fieldRule = regexp.MustCompile(`^(\*|[0-9]+(-[0-9]+)?)(/[0-9]+)?(,(\*|[0-9]+(-[0-9]+)?)(/[0-9]+)?)*$`)
)

var ranges = [5][2]int{{0, 59}, {0, 23}, {1, 31}, {1, 12}, {0, 7}}

var shortcuts = map[string]bool{"@hourly": true, "@daily": true, "@weekly": true, "@monthly": true, "@yearly": true, "@annually": true, "@midnight": true}

// file is where an account's jobs go.
func (m *Manager) file(user string) string { return filepath.Join(m.Dir, "lpanel-"+user) }

// Apply writes the account's jobs, or removes the file when there are none
// (or the account is suspended). The same jobs twice change nothing.
func (m *Manager) Apply(_ context.Context, a Args) (Result, error) {
	if !userRule.MatchString(a.Username) {
		return Result{}, protocol.Fail(protocol.CodeBadArgs, fmt.Sprintf("%q is not an account name", a.Username))
	}
	if len(a.Jobs) > MaxJobs {
		return Result{}, protocol.Fail(protocol.CodeBadArgs, fmt.Sprintf("at most %d scheduled jobs", MaxJobs))
	}
	for i, j := range a.Jobs {
		if err := j.check(); err != nil {
			return Result{}, protocol.Fail(protocol.CodeBadArgs, fmt.Sprintf("job %d: %s", i+1, err))
		}
	}
	path := m.file(a.Username)
	old, oldErr := os.ReadFile(path)

	if a.Suspended || len(a.Jobs) == 0 {
		if oldErr != nil {
			return Result{Username: a.Username}, nil
		}
		if err := os.Remove(path); err != nil {
			return Result{}, err
		}
		return Result{Username: a.Username, Changed: true}, nil
	}

	_, _, home, err := m.Owner(a.Username)
	if err != nil {
		return Result{}, err
	}
	data := []byte(render(a.Username, home, a.Jobs))
	if oldErr == nil && string(old) == string(data) {
		return Result{Username: a.Username, Jobs: len(a.Jobs)}, nil
	}
	if err := fsutil.EnsureDir(m.Dir, 0o755); err != nil {
		return Result{}, err
	}
	// cron wants its files owned by root and not writable by anyone else.
	if err := fsutil.WriteFileAtomic(path, data, 0o644); err != nil {
		return Result{}, err
	}
	if err := m.Chown(path, 0, 0); err != nil {
		return Result{}, err
	}
	return Result{Username: a.Username, Jobs: len(a.Jobs), Changed: true}, nil
}

func render(user, home string, jobs []Job) string {
	var b strings.Builder
	b.WriteString("# Generated by LPanel (cron jobs of account " + user + "). Changes made here are replaced the next time the account's jobs change.\n")
	b.WriteString("SHELL=/bin/sh\nPATH=/usr/local/bin:/usr/bin:/bin\n")
	fmt.Fprintf(&b, "HOME=%s\nMAILTO=\"\"\n", home)
	for _, k := range []string{"TMPDIR", "TMP", "TEMP"} {
		fmt.Fprintf(&b, "%s=%s/tmp\n", k, home)
	}
	b.WriteString("\n")
	for _, j := range jobs {
		fmt.Fprintf(&b, "%s %s %s\n", strings.Join(strings.Fields(j.Schedule), " "), user, strings.ReplaceAll(j.Command, "%", `\%`))
	}
	return b.String()
}

func (j Job) check() error {
	if len(j.Command) == 0 || len(j.Command) > MaxCommand {
		return fmt.Errorf("the command must be 1 to %d characters", MaxCommand)
	}
	for _, r := range j.Command {
		if r < 0x20 || r == 0x7f {
			return fmt.Errorf("the command must be one line of text")
		}
	}
	if strings.TrimSpace(j.Command) != j.Command {
		return fmt.Errorf("the command has spaces around it")
	}
	return checkSchedule(j.Schedule)
}

// checkSchedule accepts the five fields and a few @ words, and refuses what
// would run more often than every MinuteMinimum minutes.
func checkSchedule(s string) error {
	s = strings.TrimSpace(s)
	if shortcuts[s] {
		return nil
	}
	f := strings.Fields(s)
	if len(f) != 5 {
		return fmt.Errorf("the schedule is five fields (minute hour day month weekday) or @hourly, @daily, @weekly, @monthly, @yearly")
	}
	var sets [5]map[int]bool
	for i, field := range f {
		if !fieldRule.MatchString(field) {
			return fmt.Errorf("%q is not a valid schedule field", field)
		}
		set, err := expand(field, ranges[i][0], ranges[i][1])
		if err != nil {
			return err
		}
		sets[i] = set
	}
	// More than 60/MinuteMinimum minutes in an hour that runs.
	if len(sets[0]) > 60/MinuteMinimum && len(sets[1]) > 0 {
		return fmt.Errorf("a job may run at most every %d minutes", MinuteMinimum)
	}
	if len(sets[0]) > 1 {
		// Even a few minutes can be too close together: find the smallest gap (also across the hour).
		minutes := make([]int, 0, len(sets[0]))
		for m := 0; m < 60; m++ {
			if sets[0][m] {
				minutes = append(minutes, m)
			}
		}
		for i := range minutes {
			next := minutes[(i+1)%len(minutes)]
			gap := (next - minutes[i] + 60) % 60
			if len(minutes) > 1 && gap < MinuteMinimum && len(sets[1]) == 24 {
				return fmt.Errorf("a job may run at most every %d minutes", MinuteMinimum)
			}
		}
	}
	return nil
}

// expand turns one field into the numbers it names.
func expand(field string, lo, hi int) (map[int]bool, error) {
	out := map[int]bool{}
	for _, part := range strings.Split(field, ",") {
		step := 1
		if base, st, ok := strings.Cut(part, "/"); ok {
			n, err := strconv.Atoi(st)
			if err != nil || n < 1 || n > hi {
				return nil, fmt.Errorf("%q: the step must be a number from 1 to %d", part, hi)
			}
			step, part = n, base
		}
		a, b := lo, hi
		if part != "*" {
			from, to, isRange := strings.Cut(part, "-")
			x, err := strconv.Atoi(from)
			if err != nil {
				return nil, fmt.Errorf("%q is not a number", from)
			}
			a, b = x, x
			if isRange {
				y, err := strconv.Atoi(to)
				if err != nil {
					return nil, fmt.Errorf("%q is not a number", to)
				}
				b = y
			}
		}
		if a < lo || b > hi || a > b {
			return nil, fmt.Errorf("%q is outside %d to %d", part, lo, hi)
		}
		for v := a; v <= b; v += step {
			out[v] = true
		}
	}
	return out, nil
}
